using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Experimental.Rendering;
using UnityEditor;

// Isolated GPU validation only. Captured shadows and screen buffers belong to
// this oracle; production shadows must be generated by the independent URP renderer.
public static class OracleRender
{
    const string Evidence="D:/TA/Unity/New2026/TA2026/Reference/ShaderReference/EndField/Analysis/full-restore/";
    [Serializable] public class Binding { public string name,id,type,path;public int wrap,filter,mipFilter; }
    [Serializable] public class Draw { public int eid,stride,vertexCount,indexStride,indexCount; public Binding[] textures,buffers,constants; }
    [Serializable] public class Draws { public Draw[] events; }
    [Serializable] public class RawFile { public string path; public int slice,mip,bytes; }
    [Serializable] public class Resource { public string id,kind,format; public int width,height,depth,arraySize,mips;public bool cubemap; public RawFile[] files; }
    [Serializable] public class Resources { public Resource[] resources; }
    static Dictionary<string,Resource> raw;
    static Dictionary<string,Texture> textures=new Dictionary<string,Texture>();
    static Dictionary<string,GraphicsBuffer> buffers=new Dictionary<string,GraphicsBuffer>();
    static List<GraphicsBuffer> allocations=new List<GraphicsBuffer>();
    static List<string> report=new List<string>();
    static byte[] Read(string path)=>File.ReadAllBytes(Evidence+path);
    public static Texture LoadCapturedTexture(Binding binding)
    {
        if(raw==null) raw=JsonUtility.FromJson<Resources>(File.ReadAllText(Evidence+"raw-manifest-wrapped.json")).resources.ToDictionary(x=>x.id);
        return Texture(binding);
    }
    static GraphicsBuffer Buffer(byte[] bytes,GraphicsBuffer.Target target,int stride=4)
    {
        var b=new GraphicsBuffer(target,bytes.Length/stride,stride);var data=new uint[bytes.Length/4];System.Buffer.BlockCopy(bytes,0,data,0,bytes.Length);b.SetData(data);allocations.Add(b);return b;
    }
    static GraphicsFormat Format(string s)
    {
        switch(s){
        case "BC7_SRGB":return GraphicsFormat.RGBA_BC7_SRGB;
        case "BC7_UNORM":return GraphicsFormat.RGBA_BC7_UNorm;
        case "BC5_UNORM":return GraphicsFormat.RG_BC5_UNorm;
        case "BC6_UFLOAT":return GraphicsFormat.RGB_BC6H_UFloat;
        case "R8G8B8A8_SRGB":return GraphicsFormat.R8G8B8A8_SRGB;
        case "R8G8B8A8_UNORM":return GraphicsFormat.R8G8B8A8_UNorm;
        case "R8G8_UNORM":return GraphicsFormat.R8G8_UNorm;
        case "R11G11B10_FLOAT":return GraphicsFormat.B10G11R11_UFloatPack32;
        case "R32_FLOAT":return GraphicsFormat.R32_SFloat;
        case "R16G16B16A16_FLOAT":return GraphicsFormat.R16G16B16A16_SFloat;
        case "R10G10B10A2_UNORM":return GraphicsFormat.A2B10G10R10_UNormPack32;
        case "R16_TYPELESS":return GraphicsFormat.R16_UNorm;
        default:throw new Exception("Unsupported captured format "+s);}
    }
    static Texture Texture(Binding binding)
    {
        string key=binding.id+(binding.type.Contains("3D")?"-3d":"")+"-"+binding.wrap+"-"+binding.filter;
        if(textures.TryGetValue(key,out var cached))return cached;
        var r=raw[binding.id];var format=Format(r.format);Texture result;
        if(r.cubemap){
            var t=new Cubemap(r.width,format,TextureCreationFlags.MipChain,r.mips);
            foreach(var f in r.files)t.SetPixelData(Read(f.path),f.mip,(CubemapFace)f.slice);
            t.Apply(false,false);result=t;
        }else if(r.depth>1 || binding.type.Contains("3D")){
            bool packed=r.format=="R11G11B10_FLOAT";
            var t=new Texture3D(r.width,r.height,Math.Max(1,r.depth),packed?GraphicsFormat.R32G32B32A32_SFloat:format,TextureCreationFlags.None);
            foreach(var f in r.files){
                var data=Read(f.path);
                if(packed){var values=new float[data.Length];for(int i=0;i<data.Length/4;i++){uint v=BitConverter.ToUInt32(data,i*4);values[i*4]=UnsignedFloat(v&2047,6);values[i*4+1]=UnsignedFloat((v>>11)&2047,6);values[i*4+2]=UnsignedFloat(v>>22,5);values[i*4+3]=1;}t.SetPixelData(values,f.mip);}
                else t.SetPixelData(data,f.mip);
            }
            t.Apply(false,false);result=t;
        }else{
            var t=new Texture2D(r.width,r.height,format,r.mips,r.mips>1?TextureCreationFlags.MipChain:TextureCreationFlags.None);
            foreach(var f in r.files)t.SetPixelData(Read(f.path),f.mip);
            t.Apply(false,false);result=t;
        }
        result.name="Capture_"+key;result.filterMode=binding.filter==1?FilterMode.Point:binding.mipFilter==1?FilterMode.Bilinear:FilterMode.Trilinear;result.wrapMode=binding.wrap==0?TextureWrapMode.Repeat:binding.wrap==1?TextureWrapMode.Mirror:binding.wrap==2?TextureWrapMode.MirrorOnce:TextureWrapMode.Clamp;textures.Add(key,result);return result;
    }
    static float UnsignedFloat(uint value,int mantissaBits){uint exponent=value>>mantissaBits;uint mantissa=value&((1u<<mantissaBits)-1);return exponent==0?(float)(mantissa*Math.Pow(2,-14-mantissaBits)):exponent==31?(mantissa==0?float.PositiveInfinity:float.NaN):(float)((1+mantissa/(double)(1<<mantissaBits))*Math.Pow(2,(int)exponent-15));}
    static void Save(RenderTexture rt,string name)
    {
        RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBAFloat,false,true);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();
        File.WriteAllBytes(Evidence+name+".exr",image.EncodeToEXR(Texture2D.EXRFlags.OutputAsFloat));
        var pixels=image.GetPixels();for(int i=0;i<pixels.Length;i++){pixels[i]=pixels[i].gamma;pixels[i].a=1;}
        var png=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false,true);png.SetPixels(pixels);png.Apply();File.WriteAllBytes(Evidence+name+".png",png.EncodeToPNG());
        UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(png);RenderTexture.active=null;
    }
    public static void Run()
    {
        int code=0;
        try{
            PlayerSettings.colorSpace=ColorSpace.Linear;
            var draws=JsonUtility.FromJson<Draws>(File.ReadAllText(Evidence+"oracle-manifest.json"));
            raw=JsonUtility.FromJson<Resources>(File.ReadAllText(Evidence+"raw-manifest-wrapped.json")).resources.ToDictionary(x=>x.id);
            var rt=new RenderTexture(3840,2160,32,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);rt.Create();
            var cb=new CommandBuffer{name="Original source GPU oracle"};cb.SetRenderTarget(rt);cb.ClearRenderTarget(true,true,new Color(0,0,0,0),1);
            var depthBytes=Read("reference-precharacter-depth.bin");var depth=new float[3840*2160];for(int i=0;i<depth.Length;i++)depth[i]=BitConverter.ToSingle(depthBytes,i*8);
            var depthTex=new Texture2D(3840,2160,TextureFormat.RFloat,false,true);depthTex.SetPixelData(depth,0);depthTex.Apply(false);
            var background=new Texture2D(3840,2160,TextureFormat.RGBAFloat,false,true);background.LoadRawTextureData(Read("reference-background-rgba.bin"));background.Apply(false);
            var seed=new Material(Shader.Find("Hidden/FullRestoreOracle/Seed"));seed.SetTexture("_CapturedDepth",depthTex);seed.SetTexture("_CapturedBackground",background);cb.DrawProcedural(Matrix4x4.identity,seed,0,MeshTopology.Triangles,3);cb.SetInvertCulling(false);
            foreach(var d in draws.events){
                var shader=Shader.Find("Hidden/FullRestoreOracle/"+d.eid);if(!shader)throw new Exception("Missing shader "+d.eid);
                foreach(var m in ShaderUtil.GetShaderMessages(shader))if(m.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error)throw new Exception(d.eid+": "+m.message+" at "+m.line);
                var mat=new Material(shader);
                foreach(var b in d.constants){var bytes=Read(b.path);mat.SetConstantBuffer(b.name,Buffer(bytes,GraphicsBuffer.Target.Constant,16),0,bytes.Length);}
                foreach(var b in d.buffers){if(!buffers.TryGetValue(b.id,out var buf)){buf=Buffer(Read(raw[b.id].files[0].path),GraphicsBuffer.Target.Raw);buffers.Add(b.id,buf);}mat.SetBuffer(b.name,buf);}
                foreach(var b in d.textures)mat.SetTexture(b.name,Texture(b));
                mat.SetBuffer("_CapturedVertices",Buffer(Read("event-"+d.eid+"-vertices.bin"),GraphicsBuffer.Target.Structured));
                byte[] idx=Read("event-"+d.eid+"-indices.bin");var indices=new int[d.indexCount];for(int i=0;i<indices.Length;i++)indices[i]=d.indexStride==2?BitConverter.ToUInt16(idx,i*2):(int)BitConverter.ToUInt32(idx,i*4);
                var mesh=new Mesh{name="Oracle EID "+d.eid,indexFormat=IndexFormat.UInt32};mesh.vertices=new Vector3[d.vertexCount];mesh.SetIndices(indices,MeshTopology.Triangles,0,false);mesh.bounds=new Bounds(Vector3.zero,Vector3.one*10000);
                cb.DrawMesh(mesh,Matrix4x4.identity,mat);report.Add("EID "+d.eid+" vertices "+d.vertexCount+" indices "+d.indexCount);
            }
            cb.SetInvertCulling(false);Shader.SetGlobalFloat("_OracleView",0);Graphics.ExecuteCommandBuffer(cb);Save(rt,"oracle-linear");
            var samples=new[]{new Vector2Int(1930,950),new Vector2Int(1900,1170),new Vector2Int(1860,700),new Vector2Int(2000,1500),new Vector2Int(1780,2010),new Vector2Int(2030,1230)};
            foreach(int mode in new[]{14,16,17})
            {
                Shader.SetGlobalFloat("_OracleView",mode);Graphics.ExecuteCommandBuffer(cb);RenderTexture.active=rt;
                var readback=new Texture2D(rt.width,rt.height,TextureFormat.RGBAFloat,false,true);readback.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);readback.Apply();
                foreach(var p in samples)report.Add("DIAG "+mode+" "+p.x+","+p.y+" "+readback.GetPixel(p.x,rt.height-1-p.y).ToString("R"));
                UnityEngine.Object.DestroyImmediate(readback);
            }
            Shader.SetGlobalFloat("_OracleView",0);cb.Release();rt.Release();
            report.Add("GPU "+SystemInfo.graphicsDeviceName+" "+SystemInfo.graphicsDeviceType);
        }catch(Exception ex){report.Add(ex.ToString());code=1;}
        finally{foreach(var a in allocations)a.Dispose();File.WriteAllLines(Evidence+"oracle-report.txt",report);EditorApplication.Exit(code);}
    }
}
